<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\MagicLink;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\MagicLinkSession;
use Civi\Lughauth\Features\OAuth\MagicLink\Application\Usecase\VerifyMagicLink\MagicLinkVerifyResult;
use Civi\Lughauth\Features\OAuth\MagicLink\Application\Usecase\VerifyMagicLink\VerifyMagicLinkUsecase;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkCodeGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkEnabledGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkSessionGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;

final class MagicLinkDomainUnitTest extends TestCase
{
    // --- MagicLink ---

    public function test_magic_link_stores_fields(): void
    {
        $created = new DateTimeImmutable('2026-01-01T10:00:00+00:00');
        $expires = new DateTimeImmutable('2026-01-01T10:15:00+00:00');

        $ml = new MagicLink(
            uid: 'uid-1',
            tenantId: 'tenant',
            userUid: 'user-uid',
            clientId: 'client',
            tokenHash: 'hash-value',
            redirectUri: 'https://app/cb',
            scope: 'openid email',
            state: 'state-abc',
            nonce: 'nonce-xyz',
            createdAt: $created,
            expiresAt: $expires,
        );

        $this->assertSame('uid-1', $ml->uid);
        $this->assertSame('tenant', $ml->tenantId);
        $this->assertSame('user-uid', $ml->userUid);
        $this->assertSame('hash-value', $ml->tokenHash);
        $this->assertSame('state-abc', $ml->state);
        $this->assertSame('nonce-xyz', $ml->nonce);
        $this->assertNull($ml->usedAt);
    }

    public function test_magic_link_create_factory(): void
    {
        $expires = new DateTimeImmutable('+15 minutes');
        $ml = MagicLink::create('uid', 'tenant', 'user-uid', 'client', 'hash', 'https://cb', 'openid', null, $expires, 'nonce');

        $this->assertSame('uid', $ml->uid);
        $this->assertSame('nonce', $ml->nonce);
        $this->assertNull($ml->state);
        $this->assertNull($ml->usedAt);
    }

    public function test_magic_link_is_expired_when_past(): void
    {
        $past = new DateTimeImmutable('-1 second');
        $ml = new MagicLink('uid', 't', 'u', 'c', 'h', 'https://cb', 'openid', null, '', new DateTimeImmutable(), $past);
        $this->assertTrue($ml->isExpired());
    }

    public function test_magic_link_is_not_expired_when_future(): void
    {
        $future = new DateTimeImmutable('+60 seconds');
        $ml = new MagicLink('uid', 't', 'u', 'c', 'h', 'https://cb', 'openid', null, '', new DateTimeImmutable(), $future);
        $this->assertFalse($ml->isExpired());
    }

    public function test_magic_link_is_used_when_used_at_not_null(): void
    {
        $future = new DateTimeImmutable('+60 seconds');
        $ml = new MagicLink('uid', 't', 'u', 'c', 'h', 'https://cb', 'openid', null, '', new DateTimeImmutable(), $future, new DateTimeImmutable());
        $this->assertTrue($ml->isUsed());
    }

    public function test_magic_link_is_valid_when_not_expired_and_not_used(): void
    {
        $future = new DateTimeImmutable('+60 seconds');
        $ml = new MagicLink('uid', 't', 'u', 'c', 'h', 'https://cb', 'openid', null, '', new DateTimeImmutable(), $future, null);
        $this->assertTrue($ml->isValid());
    }

    public function test_magic_link_is_invalid_when_expired(): void
    {
        $past = new DateTimeImmutable('-1 second');
        $ml = new MagicLink('uid', 't', 'u', 'c', 'h', 'https://cb', 'openid', null, '', new DateTimeImmutable(), $past, null);
        $this->assertFalse($ml->isValid());
    }

    // --- MagicLinkSession ---

    public function test_magic_link_session_stores_fields(): void
    {
        $exp = new DateInterval('PT1H');
        $session = new MagicLinkSession('sess-id-123', $exp);

        $this->assertSame('sess-id-123', $session->sessionId);
        $this->assertSame($exp, $session->expiration);
    }

    // --- MagicLinkVerifyResult ---

    public function test_magic_link_verify_result_with_session(): void
    {
        $session = new MagicLinkSession('s', new DateInterval('PT1H'));
        $r = new MagicLinkVerifyResult('https://app/cb?code=abc', $session);

        $this->assertSame('https://app/cb?code=abc', $r->redirectUrl);
        $this->assertSame($session, $r->session);
    }

    public function test_magic_link_verify_result_without_session(): void
    {
        $r = new MagicLinkVerifyResult('https://app/cb?code=abc', null);
        $this->assertNull($r->session);
    }

    // --- VerifyMagicLinkUsecase ---

    public function test_verify_throws_when_feature_disabled(): void
    {
        $this->expectException(\DomainException::class);

        $usecase = $this->buildVerifyUsecase(enabled: false);
        $usecase->verify('raw-token', 'client', 'tenant');
    }

    public function test_verify_throws_when_token_not_found(): void
    {
        $this->expectException(\DomainException::class);

        $usecase = $this->buildVerifyUsecase(enabled: true, magicLink: null);
        $usecase->verify('raw-token', 'client', 'tenant');
    }

    public function test_verify_throws_when_client_id_mismatch(): void
    {
        $this->expectException(\DomainException::class);

        $ml = $this->makeMagicLink(clientId: 'other-client');
        $usecase = $this->buildVerifyUsecase(enabled: true, magicLink: $ml);
        $usecase->verify('raw-token', 'client', 'tenant');
    }

    public function test_verify_returns_result_with_redirect_url(): void
    {
        $ml = $this->makeMagicLink(clientId: 'client', redirectUri: 'https://app/cb', state: 'xyz');
        $usecase = $this->buildVerifyUsecase(enabled: true, magicLink: $ml);

        $result = $usecase->verify('raw-token', 'client', 'tenant');

        $this->assertStringContainsString('https://app/cb', $result->redirectUrl);
        $this->assertStringContainsString('code=', $result->redirectUrl);
        $this->assertStringContainsString('state=xyz', $result->redirectUrl);
    }

    public function test_verify_omits_state_from_redirect_when_null(): void
    {
        $ml = $this->makeMagicLink(clientId: 'client', redirectUri: 'https://app/cb', state: null);
        $usecase = $this->buildVerifyUsecase(enabled: true, magicLink: $ml);

        $result = $usecase->verify('raw-token', 'client', 'tenant');

        $this->assertStringNotContainsString('state=', $result->redirectUrl);
    }

    // --- helpers ---

    private function makeMagicLink(
        string $clientId = 'client',
        string $redirectUri = 'https://app/cb',
        ?string $state = null
    ): MagicLink {
        $future = new DateTimeImmutable('+60 seconds');
        return new MagicLink(
            uid: 'ml-uid',
            tenantId: 'tenant',
            userUid: 'user-uid',
            clientId: $clientId,
            tokenHash: hash('sha256', 'raw-token'),
            redirectUri: $redirectUri,
            scope: 'openid',
            state: $state,
            nonce: '',
            createdAt: new DateTimeImmutable(),
            expiresAt: $future,
            usedAt: null
        );
    }

    private function buildVerifyUsecase(bool $enabled, ?MagicLink $magicLink = null): VerifyMagicLinkUsecase
    {
        $gateway = new class($magicLink) implements MagicLinkGateway {
            public function __construct(private ?MagicLink $ml) {}
            public function store(MagicLink $magicLink): void {}
            public function findByHash(string $tokenHash, string $tenantId): ?MagicLink { return $this->ml; }
            public function markUsed(string $uid): void {}
        };

        $codeGateway = new class() implements MagicLinkCodeGateway {
            public function createAuthCode(string $userUid, string $clientId, string $scope, string $redirectUri, string $tenant, string $nonce = ''): string
            {
                return 'auth-code-test';
            }
        };

        $enabledGateway = new class($enabled) implements MagicLinkEnabledGateway {
            public function __construct(private bool $enabled) {}
            public function isEnabled(string $tenantName): bool { return $this->enabled; }
        };

        $sessionGateway = new class() implements MagicLinkSessionGateway {
            public function createSession(string $userUid, string $email, string $tenantUid, string $tenantName, string $clientId): ?MagicLinkSession
            {
                return new MagicLinkSession('sess-123', new DateInterval('PT1H'));
            }
        };

        $tenants = new class() implements TenantReadGateway {
            public function resolve(\Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef $ref): ?\Civi\Lughauth\Features\Access\Tenant\Domain\Tenant { return null; }
            public function list(?\Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantFilter $filter = null, ?\Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantCursor $cursor = null): \Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantSlide { throw new \RuntimeException('not used'); }
            public function retrieve(?\Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantFilter $filter): ?\Civi\Lughauth\Features\Access\Tenant\Domain\Tenant { return null; }
            public function exists(?\Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantFilter $filter): bool { return false; }
            public function count(?\Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantFilter $filter = null): int { return 0; }
            public function findOneByUid(string $uid): ?\Civi\Lughauth\Features\Access\Tenant\Domain\Tenant { return null; }
            public function findOneByName(string $name): ?\Civi\Lughauth\Features\Access\Tenant\Domain\Tenant { return null; }
            public function findOneByDomain(string $domain): ?\Civi\Lughauth\Features\Access\Tenant\Domain\Tenant { return null; }
        };

        $users = new class() implements UserReadGateway {
            public function resolve(\Civi\Lughauth\Features\Access\User\Domain\UserRef $ref): ?\Civi\Lughauth\Features\Access\User\Domain\User { return null; }
            public function list(?\Civi\Lughauth\Features\Access\User\Domain\Gateway\UserFilter $filter = null, ?\Civi\Lughauth\Features\Access\User\Domain\Gateway\UserCursor $cursor = null): \Civi\Lughauth\Features\Access\User\Domain\Gateway\UserSlide { throw new \RuntimeException('not used'); }
            public function retrieve(\Civi\Lughauth\Features\Access\User\Domain\Gateway\UserFilter $filter): ?\Civi\Lughauth\Features\Access\User\Domain\User { return null; }
            public function exists(\Civi\Lughauth\Features\Access\User\Domain\Gateway\UserFilter $filter): bool { return false; }
            public function count(?\Civi\Lughauth\Features\Access\User\Domain\Gateway\UserFilter $filter = null): int { return 0; }
            public function findOneByUid(string $uid): ?\Civi\Lughauth\Features\Access\User\Domain\User { return null; }
            public function findOneByTenantAndName(\Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef $tenant, string $name): ?\Civi\Lughauth\Features\Access\User\Domain\User { return null; }
        };

        return new VerifyMagicLinkUsecase($gateway, $codeGateway, $enabledGateway, $sessionGateway, $tenants, $users);
    }
}
